INSERT INTO `wp_postmeta` VALUES (155, 567, '_tutor_course_benefits', 'Become a UX designer.\r\nYou will be able to start earning money from your XD Skills.\r\nYou will be able to add UX designer to your CV\r\nBuild a UX project from beginning to end.\r\nBecome a UI designer.\r\nBuild &amp; test a full mobile app.');
INSERT INTO `wp_postmeta` VALUES (156, 567, '_tutor_course_requirements', 'You will need a copy of Adobe XD 2019 or above.\r\nNo previous design experience is needed.\r\nNo previous Adobe XD skills are needed.');
INSERT INTO `wp_postmeta` VALUES (157, 567, '_tutor_course_target_audience', 'Anyone who wants to start using Adobe XD in their career &amp; get paid for their user experience design skills.\r\nThis course is for beginners, newbies &amp; amateurs in the field of UX design.\r\nAimed at people new to the world of design &amp; user experience.\r\nFor anyone that needs to add ‘UX Design’ to their portfolio.');
INSERT INTO `wp_postmeta` VALUES (158, 567, '_tutor_course_material_includes', '11.5 hours on-demand video\r\n69 downloadable resources\r\nFull lifetime access\r\nAccess on mobile and TV\r\nAssignments\r\nCertificate of Completion');
