  INDEX `order_type`(`order_type` ASC) USING BTREE,
  INDEX `payment_status`(`payment_status` ASC) USING BTREE,
  INDEX `order_status`(`order_status` ASC) USING BTREE,
  INDEX `transaction_id`(`transaction_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci ROW_FORMAT = Dynamic;

